import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const indexPath = path.join(root, "public", "data", "content-index.json");
const outputDir = path.join(root, ".generated");
const outputFile = path.join(outputDir, "search-seed.sql");

const { pages } = JSON.parse(await readFile(indexPath, "utf8"));

const sql = [
  "-- Generated by scripts/build-search-index.mjs. Do not edit by hand.",
  "DELETE FROM page_terms;",
  "DELETE FROM pages_fts;",
  "DELETE FROM pages;",
  ...pages.flatMap(pageToSql),
  "",
].join("\n");

await mkdir(outputDir, { recursive: true });
await writeFile(outputFile, sql, "utf8");

console.log(`Generated D1 seed for ${pages.length} pages at ${path.relative(root, outputFile)}`);

function pageToSql(page) {
  const rows = [
    `INSERT INTO pages (slug, title, kind, source_path, description, formula, nominal_mass, precursor1, family_json, species_json, level, confidence, categories_json, tags_json) VALUES (${sqlString(page.slug)}, ${sqlString(page.title)}, ${sqlString(page.kind)}, ${sqlString(page.sourcePath)}, ${sqlString(page.description)}, ${sqlString(page.formula)}, ${sqlNumber(page.nominalMass)}, ${sqlNumber(page.precursor1)}, ${sqlString(JSON.stringify(page.family))}, ${sqlString(JSON.stringify(page.species))}, ${sqlString(page.level)}, ${sqlString(page.confidence)}, ${sqlString(JSON.stringify(page.categories))}, ${sqlString(JSON.stringify(page.tags))});`,
    `INSERT INTO pages_fts (slug, title, body, formula, categories, tags, families, species) VALUES (${sqlString(page.slug)}, ${sqlString(page.title)}, ${sqlString(page.bodyText)}, ${sqlString(page.formula)}, ${sqlString(page.categories.join(" "))}, ${sqlString(page.tags.join(" "))}, ${sqlString(page.family.join(" "))}, ${sqlString(page.species.join(" "))});`,
  ];

  const terms = [
    ...page.categories.map((value) => ["category", value]),
    ...page.tags.map((value) => ["tag", value]),
    ...page.family.map((value) => ["family", value]),
    ...page.species.map((value) => ["species", value]),
    page.formula ? ["formula", page.formula] : null,
    page.level ? ["level", page.level] : null,
    page.confidence ? ["confidence", page.confidence] : null,
  ].filter(Boolean);

  for (const [type, value] of terms) {
    rows.push(`INSERT INTO page_terms (page_slug, term_type, term_value) VALUES (${sqlString(page.slug)}, ${sqlString(type)}, ${sqlString(value)});`);
  }

  return rows;
}

function sqlString(value) {
  return `'${String(value ?? "").replaceAll("'", "''")}'`;
}

function sqlNumber(value) {
  return Number.isFinite(value) ? String(value) : "NULL";
}
